package tv.casa.launcher;

import android.content.*;
import android.graphics.BitmapFactory;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.net.HttpURLConnection;
import java.util.*;

/** Content-addressed image cache. Only missing images are fetched, on a user action. */
final class OnlineAmbientStore {
    static final Object LOCK=new Object();
    private final Context context;private final File root;final AmbientHttp http=new AmbientHttp();
    OnlineAmbientStore(Context c){context=c.getApplicationContext();root=new File(c.getFilesDir(),"ambient-online");}
    SharedPreferences prefs(){return context.getSharedPreferences("AmbientOnline",0);}
    private void ready()throws IOException{if(!root.isDirectory()&&!root.mkdirs())throw new IOException("Almacenamiento no disponible");}
    private byte[] read(File f,int limit)throws Exception{try(InputStream in=new FileInputStream(f)){ByteArrayOutputStream out=new ByteArrayOutputStream();GalleryPolicy.copy(in,out,limit);return out.toByteArray();}}
    AmbientCatalog catalog()throws Exception{File file=new File(root,"catalog.json");if(file.isFile()&&prefs().getString("cachedCatalogUrl","").equals(prefs().getString("catalogUrl",OnlinePolicy.DEFAULT_CATALOG)))try{return AmbientCatalog.parse(new String(read(file,OnlinePolicy.MAX_CATALOG),StandardCharsets.UTF_8));}catch(Exception ignored){}try(InputStream in=context.getAssets().open("ambient-catalog-v2.json")){ByteArrayOutputStream out=new ByteArrayOutputStream();GalleryPolicy.copy(in,out,OnlinePolicy.MAX_CATALOG);return AmbientCatalog.parse(new String(out.toByteArray(),StandardCharsets.UTF_8));}}
    void refresh()throws Exception{ready();String url=prefs().getString("catalogUrl",OnlinePolicy.DEFAULT_CATALOG);if(!OnlinePolicy.https(url))throw new IOException("URL no válida");String cached=prefs().getString("etagUrl","").equals(url)?prefs().getString("etag",""):"";byte[] data=http.fetch(url,OnlinePolicy.MAX_CATALOG,new File(root,"catalog.json").isFile()?cached:"");if(data!=null){AmbientCatalog.parse(new String(data,StandardCharsets.UTF_8));writeAtomic(new File(root,"catalog.json"),data);String tag=http.lastEtag;prefs().edit().putString("etag",tag==null?"":tag).putString("etagUrl",url).putString("cachedCatalogUrl",url).apply();}prefs().edit().putLong("catalogChecked",System.currentTimeMillis()).apply();}
    private void writeAtomic(File target,byte[] bytes)throws Exception{File part=new File(root,target.getName()+".part");try{try(FileOutputStream out=new FileOutputStream(part)){out.write(bytes);out.getFD().sync();}android.system.Os.rename(part.getPath(),target.getPath());}finally{if(part.exists())part.delete();}}
    File file(AmbientCatalog.Variant v){return new File(root,v.sha+".img");}
    boolean cached(AmbientCatalog.Variant v){File f=file(v);return f.isFile()&&f.length()==v.bytes;}
    int targetWidth(){return Math.min(3840,context.getResources().getDisplayMetrics().widthPixels);}
    ArrayList<AmbientCatalog.Item> selected(AmbientCatalog data){ArrayList<AmbientCatalog.Item> out=new ArrayList<>();String selection=prefs().getString("collection","all");boolean exists=selection.equals("all")||selection.equals("favorites");for(AmbientCatalog.Collection c:data.collections)if(c.id.equals(selection))exists=true;if(!exists)selection="all";Set<String> favorites=prefs().getStringSet("favorites",Collections.emptySet());for(AmbientCatalog.Collection c:data.collections)if(selection.equals("all")||selection.equals("favorites")||selection.equals(c.id))for(AmbientCatalog.Item m:c.items)if(m.image()&&(!selection.equals("favorites")||favorites.contains(m.id)))out.add(m);return out;}
    ArrayList<AmbientCatalog.Item> local(AmbientCatalog data){ArrayList<AmbientCatalog.Item> out=new ArrayList<>();for(AmbientCatalog.Item m:selected(data))if(cached(m.choose(targetWidth())))out.add(m);return out;}
    int downloadSelection()throws Exception{synchronized(LOCK){ready();File[] abandoned=root.listFiles((d,n)->n.matches("[a-f0-9]{64}\\.part"));if(abandoned!=null)for(File f:abandoned)if(!f.delete())throw new IOException("No se pudo limpiar una descarga anterior");AmbientCatalog data=catalog();ArrayList<AmbientCatalog.Item> selected=selected(data);if(selected.isEmpty())throw new IOException("Selecciona una colección con imágenes");HashSet<String> keep=new HashSet<>();long total=0;for(AmbientCatalog.Item item:selected){AmbientCatalog.Variant v=item.choose(targetWidth());if(keep.add(v.sha))total+=v.bytes;}if(total>OnlinePolicy.CACHE_BYTES)throw new IOException("La colección supera 64 MiB");
        int fetched=0;for(AmbientCatalog.Item item:selected){http.check();AmbientCatalog.Variant v=item.choose(targetWidth());if(cached(v)&&GalleryPolicy.sha256(file(v)).equals(v.sha)){file(v).setLastModified(System.currentTimeMillis());continue;}if(file(v).exists()&&!file(v).delete())throw new IOException("No se pudo reemplazar una imagen dañada");prune(v.bytes,keep);byte[] bytes=http.fetch(v.url,v.bytes,null);if(bytes==null||bytes.length!=v.bytes)throw new IOException("Tamaño de imagen no válido");File part=new File(root,v.sha+".part");try{try(FileOutputStream out=new FileOutputStream(part)){out.write(bytes);}if(!GalleryPolicy.sha256(part).equals(v.sha))throw new IOException("La imagen no coincide con el catálogo");BitmapFactory.Options b=new BitmapFactory.Options();b.inJustDecodeBounds=true;BitmapFactory.decodeFile(part.getPath(),b);if(!OnlinePolicy.dimensions(b.outWidth,b.outHeight)||b.outWidth!=v.width||b.outHeight!=v.height||(!"image/jpeg".equals(b.outMimeType)&&!"image/png".equals(b.outMimeType)&&!"image/webp".equals(b.outMimeType)))throw new IOException("Imagen no compatible");b.inJustDecodeBounds=false;b.inSampleSize=8;android.graphics.Bitmap probe=BitmapFactory.decodeFile(part.getPath(),b);if(probe==null)throw new IOException("Imagen dañada");probe.recycle();http.check();android.system.Os.rename(part.getPath(),file(v).getPath());fetched++;}finally{if(part.exists())part.delete();}}
        prefs().edit().putInt("lastFetched",fetched).apply();return local(data).size();}}
    private void prune(long incoming,Set<String> keep)throws IOException{File[] files=root.listFiles((d,n)->n.matches("[a-f0-9]{64}\\.img"));if(files==null)files=new File[0];Arrays.sort(files,Comparator.comparingLong(File::lastModified));long size=0;for(File f:files)size+=f.length();for(File f:files){if(size+incoming<=OnlinePolicy.CACHE_BYTES)break;if(!keep.contains(f.getName().substring(0,64))){long n=f.length();if(f.delete())size-=n;}}if(size+incoming>OnlinePolicy.CACHE_BYTES)throw new IOException("No hay espacio en la caché");}
    long bytes(){long total=0;File[] list=root.listFiles((d,n)->n.endsWith(".img"));if(list!=null)for(File f:list)total+=f.length();return total;}
    void clear()throws Exception{synchronized(LOCK){File[] list=root.listFiles((d,n)->n.matches("[a-f0-9]{64}\\.(img|part)"));if(list!=null)for(File f:list)if(!f.delete())throw new IOException("No se pudo borrar la caché");prefs().edit().putBoolean("enabled",false).apply();}}
    void favorite(String id){Set<String> values=new HashSet<>(prefs().getStringSet("favorites",Collections.emptySet()));if(!values.remove(id))values.add(id);prefs().edit().putStringSet("favorites",values).apply();}
    void cancel(){http.cancel();}
}
